test('primary palette and body colors satisfy normal text contrast',async()=>{const css=await readFile(path.join(here,'src/style.css'),'utf8');const lum=hex=>{const vals=hex.match(/\w\w/g).map(c=>parseInt(c,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return vals[0]*.2126+vals[1]*.7152+vals[2]*.0722;};const ratio=(a,b)=>{const aa=lum(a),bb=lum(b);return (Math.max(aa,bb)+.05)/(Math.min(aa,bb)+.05);};assert.match(css,/--red:#d71e28/);for(const [fg,bg] of [['ffffff','d71e28'],['3b3331','f4f0ed'],['64615d','f4f0ed'],['736c63','ffffff']])assert.ok(ratio(fg,bg)>=4.5,`${fg}/${bg}`);assert.match(css,/prefers-reduced-motion:reduce/);assert.match(css,/:focus-visible/);});

