test('lost committed response retries identical key, input and revision',async()=>{
 const pending=new api.PendingTransaction(), session={session_id:'session-a',revision:0};let committed=0;const replies=new Map();
 const send=async attempt=>{if(replies.has(attempt.key))return replies.get(attempt.key);committed++;replies.set(attempt.key,{revision:1});throw new Error('Response lost after commit');};
 const source={AGE:18};const first=pending.prepare('ELIG',session,source,()=> 'key-1');source.AGE=19;
 await assert.rejects(send(first),/Response lost/);
 const retry=pending.prepare('ELIG',session,{AGE:20},()=> 'key-2');assert.strictEqual(first,retry);assert.equal(retry.body.record.AGE,18);
 assert.deepEqual(await send(retry),{revision:1});assert.equal(committed,1);pending.received(200);assert.equal(pending.attempt,null);
});
test('pending operation cannot drift into another session and uncertain errors keep identity',()=>{
 const pending=new api.PendingTransaction();pending.prepare('ELIG',{session_id:'a',revision:3},{},()=> 'key');
 for(const status of [408,429,500,503]){pending.received(status);assert.equal(pending.attempt.key,'key');}
 assert.throws(()=>pending.prepare('ELIG',{session_id:'b',revision:3},{}),/End the pending session/);
 pending.received(422);assert.equal(pending.attempt,null);
});
test('pending transaction preserves a valid PIC9(18) numeric literal without rounding',()=>{
 const pending=new api.PendingTransaction();
 const attempt=pending.prepare('TEST',{session_id:'exact-session',revision:0},{AMOUNT:9007199254740993n,DECISION:' '},()=> 'exact-key');
 assert.equal(attempt.body.record.AMOUNT,9007199254740993n);
 assert.equal(attempt.serializedBody,'{"record":{"AMOUNT":9007199254740993,"DECISION":" "},"revision":0}');
});

