const pollingOutput=path.resolve(here,'../.implementation/tmp/ui-tests/polling-interactions.cjs');
await build({stdin:{contents:`export * from './src/usePolling';`,resolveDir:here,loader:'ts'},bundle:true,platform:'node',format:'cjs',outfile:pollingOutput,plugins:[{name:'polling-test-adapter',setup(builder){builder.onLoad({filter:/usePolling\.ts$/},async args=>({contents:(await readFile(args.path,'utf8')).replace("import {useEffect,useRef} from 'react';",`export const __pollProbe={effect:null,schedule:null,cancel:null,document:null,fetch:null};const useRef=(value)=>({current:value});const useEffect=(effect)=>{__pollProbe.effect=effect;};`).replaceAll('document.','__pollProbe.document.').replaceAll('await fetch(','await __pollProbe.fetch(').replaceAll('setTimeout(','__pollProbe.schedule(').replaceAll('clearTimeout(','__pollProbe.cancel('),loader:'ts'}));}}],logLevel:'silent'});
const pollingProbe=createRequire(import.meta.url)(pollingOutput);
test('real polling sends changed snapshots once, recovers same snapshot after failure and cleans pending work',async()=>{const pending=[],values=[],failures=[],listeners=new Map();let state={revision:1},reject=false;const p=pollingProbe.__pollProbe;p.document={hidden:false,addEventListener:(name,handler)=>listeners.set(name,handler),removeEventListener:name=>listeners.delete(name)};p.schedule=handler=>{pending.push(handler);return handler;};p.cancel=handler=>{const index=pending.indexOf(handler);if(index>=0)pending.splice(index,1);};p.fetch=async()=>{if(reject)throw Error('Synthetic offline');return {ok:true,json:async()=>({...state})};};pollingProbe.usePolling('/synthetic',value=>values.push(value),error=>failures.push(error.message));const cleanup=p.effect(),flush=()=>new Promise(resolve=>setImmediate(resolve));await flush();assert.equal(values.length,1);pending.shift()();await flush();assert.equal(values.length,1);state={revision:2};pending.shift()();await flush();assert.deepEqual(values,[{revision:1},{revision:2}]);reject=true;pending.shift()();await flush();assert.deepEqual(failures,['Synthetic offline']);reject=false;pending.shift()();await flush();assert.deepEqual(values,[{revision:1},{revision:2},{revision:2}]);cleanup();assert.equal(pending.length,0);assert.equal(listeners.size,0);});

